import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """DSATUR-style saturation: distinct colours among a vertex's coloured neighbours, scaled by colours used + 1, with residual-degree as a within-saturation tie-break."""
    nc = np.asarray(neighbor_colors)
    k, c = nc.shape
    if k == 0:
        return np.zeros(0, dtype=float)
    if c == 0:
        return np.zeros(k, dtype=float)
    sat = (nc > 0).sum(axis=1).astype(float)          # distinct neighbour colours
    res_deg = np.asarray(adjacency).sum(axis=1).astype(float)  # uncoloured-neighbour count
    return (sat + 0.5 * res_deg / (k + 1.0)) / (c + 1.0)
```

